<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {runtime} from './ipc';import type {ManagedView,Method} from './generated/protocol';
const view=ref<ManagedView|null>(null),selected=ref(''),error=ref(''),busy=reactive(new Set<string>()),editing=ref(false),importing=ref(false),name=ref(''),source=ref(''),files=ref<Record<string,string>>({}),file=ref(''),baseline=ref('');
const checks=ref('{"cases":[{"args":[1],"kwargs":{},"expected":2}],"timeout_secs":60,"require_regression":false,"replay_safe":false,"output_budget_bytes":1048576}');
const current=computed(()=>view.value?.candidates.find(c=>c.id===selected.value));
const dirty=computed(()=>importing.value?!!(name.value||source.value):editing.value&&JSON.stringify(files.value)!==baseline.value);
async function run(key:string,command:Method){busy.add(key);error.value='';try{const r=await runtime.operation(command);if(r.kind!=='managed')throw new Error('Managed Skills 响应无效');view.value=r.data;return true;}catch(e){error.value=String(e);return false;}finally{busy.delete(key);}}
async function save(){if(!view.value?.current)return false;const ok=importing.value?await run('edit',{method:'managed_import',params:{base:view.value.current.id,name:name.value,source:source.value}}):await run('edit',{method:'managed_edit',params:{id:selected.value,files:files.value}});if(ok)discard();return ok;}
function edit(){if(!current.value)return;files.value={...current.value.files};file.value=Object.keys(files.value)[0]??'';baseline.value=JSON.stringify(files.value);editing.value=true;}
function discard(){editing.value=false;importing.value=false;name.value='';source.value='';}
function validate(){try{JSON.parse(checks.value);}catch{error.value='验证用例需要合法 JSON';return;}return run(selected.value,{method:'managed_validate',params:{id:selected.value,checks:checks.value}});}
function publish(){return run(selected.value,{method:'managed_publish',params:{id:selected.value,update_id:crypto.randomUUID()}});}
function rollback(target:string){if(view.value?.current)return run('history',{method:'managed_rollback',params:{base:view.value.current.id,target,update_id:crypto.randomUUID()}});}
defineExpose({dirty,save,discard});onMounted(()=>run('read',{method:'managed_read'}));
</script>
<template><div class="panel"><p v-if="error" role="alert" class="failure">{{error}}</p><p v-if="view?.issue" class="failure">{{view.issue}}</p><p v-if="!view?.current">请在运行环境中初始化 Python，以建立可验证的发布环境。</p>
 <form v-if="importing" @submit.prevent="save"><fieldset :disabled="busy.has('edit')"><label>候选名称<input v-model="name" required/></label><label>候选源目录<input v-model="source" required/></label><small>目录应包含 SKILL.md、pyproject.toml 和 Python 源码。导入会冻结副本。</small><div class="actions"><button type="submit">生成候选</button><button type="button" @click="discard">放弃</button></div></fieldset></form>
 <template v-else-if="editing"><label>文件<select v-model="file"><option v-for="(_,path) in files" :key="path">{{path}}</option></select></label><label>内容<textarea v-if="file" v-model="files[file]" rows="18" :disabled="busy.has('edit')"/></label><div class="actions"><button :disabled="busy.has('edit')" @click="save">保存为新候选</button><button :disabled="busy.has('edit')" @click="discard">放弃编辑</button></div></template>
 <template v-else><p class="path">当前发布：{{view?.current?.id}}</p><div class="actions"><button :disabled="!view?.current" @click="importing=true">导入候选</button><button :disabled="busy.has('read')" @click="run('read',{method:'managed_read'})">重新读取</button></div><div class="resource-list"><button v-for="candidate in view?.candidates" :key="candidate.id" :class="{selected:selected===candidate.id}" @click="selected=candidate.id">{{candidate.name}} · {{candidate.state}}<small>{{candidate.revision.slice(0,16)}}</small></button></div>
 <article v-if="current" class="resource-detail"><p class="path">基线：{{current.base}}</p><p>依赖：{{current.dependencies.join(', ')||'无额外依赖'}}</p><div class="actions"><button :disabled="busy.has(selected)" @click="edit">编辑候选</button><button :disabled="busy.has(selected)" @click="run(selected,{method:'managed_dependencies',params:{id:selected}})">请求依赖准备</button></div><small>依赖请求更新初始化范围；随后在运行环境中显式初始化。</small><label>验证用例（JSON）<textarea v-model="checks" rows="7" :disabled="busy.has(selected)"/></label><div class="actions"><button :disabled="busy.has(selected)" @click="validate">执行验证</button><button :disabled="!busy.has(selected)" @click="run('cancel',{method:'managed_cancel',params:{id:selected}})">取消验证</button><button :disabled="busy.has(selected)||current.state!=='validated'" @click="publish">发布已验证候选</button></div><p v-if="busy.has(selected)">操作进行中…</p><pre>{{current.result}}</pre><small>重启后需要重新验证，才允许发布。验证失败保留当前发布版本。</small></article>
 <h3>发布历史</h3><details v-for="publication in view?.history" :key="publication.id"><summary>{{publication.id.slice(0,16)}}</summary><p>技能：{{publication.skills.join(', ')||'无'}}</p><p class="path">{{publication.environment}}</p><button :disabled="busy.has('history')||view?.current?.id===publication.id" @click="rollback(publication.id)">回滚到此发布</button></details></template>
</div></template>
